import java.util.ArrayList;
import java.util.List;

public class AgendaSnapshotTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        List<Meeting> source = new ArrayList<>();
        Meeting standup = new Meeting("Standup", 15);
        source.add(standup);
        source.add(new Meeting("Review", 45));

        AgendaSnapshot snapshot = new AgendaSnapshot(source);
        check("size", 2, snapshot.size());
        check("titles", "Standup, Review", snapshot.titles());
        check("totalMinutes", 60, snapshot.totalMinutes());

        source.add(new Meeting("Retro", 30));
        check("growing the source list does not grow the snapshot", 2, snapshot.size());

        standup.setTitle("HIJACKED");
        standup.setMinutes(999);
        check("mutating the source meeting does not change the snapshot",
                "Standup, Review", snapshot.titles());
        check("nor its total", 60, snapshot.totalMinutes());

        try {
            List<Meeting> handed = snapshot.meetings();
            handed.get(0).setTitle("ALSO HIJACKED");
            handed.add(new Meeting("Extra", 5));
            check("mutating a handed-out meeting does not change the snapshot",
                    "Standup, Review", snapshot.titles());
            check("nor does adding to the handed-out list", 2, snapshot.size());
        } catch (RuntimeException e) {
            System.out.println("FAIL  meetings() must hand back a usable list of copies"
                    + " -- expected 2 meetings but the returned list could not be used");
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

