import java.util.ArrayList;
import java.util.List;

/**
 * TASK: Complete AgendaSnapshot so that nothing outside it can reach the
 * Meeting objects it holds. The Meeting class above it is provided and
 * already works (note its copy() helper) -- do not change it.
 *
 * Meeting is MUTABLE, so storing the caller's list is not enough: two
 * references to the same Meeting are the same object, and whoever holds the
 * other reference can rewrite the snapshot. Copy on the way IN and on the
 * way OUT.
 *
 * Rules:
 *   - the constructor stores a copy of the list AND a copy of every Meeting
 *     in it; a null list means an empty snapshot
 *   - meetings() hands back a new list of fresh copies every time
 *   - titles() joins the stored titles with ", " ("" when empty)
 *   - totalMinutes() adds up the stored durations
 *
 * Example: after new AgendaSnapshot(list), calling list.get(0).setTitle("X")
 *   must NOT change titles().
 */
class Meeting {

    private String title;
    private int minutes;

    Meeting(String title, int minutes) {
        this.title = title;
        this.minutes = minutes;
    }

    String getTitle() {
        return title;
    }

    void setTitle(String title) {
        this.title = title;
    }

    int getMinutes() {
        return minutes;
    }

    void setMinutes(int minutes) {
        this.minutes = minutes;
    }

    Meeting copy() {
        return new Meeting(title, minutes);
    }
}

public class AgendaSnapshot {

    private final List<Meeting> meetings = new ArrayList<>();

    public AgendaSnapshot(List<Meeting> source) {
        if (source == null) {
            return;
        }
        for (Meeting meeting : source) {
            if (meeting != null) {
                meetings.add(meeting.copy());
            }
        }
    }

    public int size() {
        return meetings.size();
    }

    public List<Meeting> meetings() {
        List<Meeting> copies = new ArrayList<>();
        for (Meeting meeting : meetings) {
            copies.add(meeting.copy());
        }
        return copies;
    }

    public String titles() {
        StringBuilder text = new StringBuilder();
        for (Meeting meeting : meetings) {
            if (text.length() > 0) {
                text.append(", ");
            }
            text.append(meeting.getTitle());
        }
        return text.toString();
    }

    public int totalMinutes() {
        int total = 0;
        for (Meeting meeting : meetings) {
            total = total + meeting.getMinutes();
        }
        return total;
    }
}
